'{
  "data": {
    "name": "dataset"
  },
  "width": "container",
  "height": "container",
  "padding": {
    "right": 96
  },
  "transform": [
    {
      "filter": "datum[''Não realizada (GWh)''] > 0"
    }
  ],
  "encoding": {
    "y": {
      "field": "Estado",
      "type": "nominal",
      "sort": {
        "field": "% cortado",
        "op": "max",
        "order": "descending"
      },
      "title": null,
      "axis": {
        "ticks": false,
        "labelLimit": 140
      }
    }
  },
  "layer": [
    {
      "mark": {
        "type": "bar",
        "height": {
          "band": 0.7
        }
      },
      "encoding": {
        "x": {
          "field": "% cortado",
          "type": "quantitative",
          "title": null,
          "axis": {
            "format": ".0%",
            "tickCount": 4
          }
        },
        "color": {
          "condition": {
            "test": "datum[''% cortado''] >= 0.2",
            "value": "#F2C811"
          },
          "value": "#252423"
        },
        "tooltip": [
          {
            "field": "Estado"
          },
          {
            "field": "% cortado",
            "format": ".1%"
          },
          {
            "field": "Não realizada (GWh)",
            "title": "Não realizada (GWh)",
            "format": ",.0f"
          }
        ],
        "opacity": {
          "condition": {
            "test": "datum.__selected__ == ''off''",
            "value": 0.25
          },
          "value": 1
        }
      }
    },
    {
      "mark": {
        "type": "text",
        "align": "left",
        "dx": 4,
        "fontSize": 9,
        "color": "#605E5C"
      },
      "encoding": {
        "x": {
          "field": "% cortado",
          "type": "quantitative"
        },
        "text": {
          "value": {
            "expr": "format(datum[''% cortado''], ''.1%'') + '' · '' + format(datum[''Não realizada (GWh)''], '',.0f'') + '' GWh''"
          }
        },
        "opacity": {
          "condition": {
            "test": "datum.__selected__ == ''off''",
            "value": 0.25
          },
          "value": 1
        }
      }
    }
  ]
}'
